#include <stdint.h>
#include "stm32f411xe.h"
#include "stm32f4xx.h"


void init_gpio(void);
void init_tim3(void);

int main(void) {
    //COnfigurar el hardware abntes de la función principal
    init_gpio(); //configuramos los pines GPIO
    init_tim3(); //configuramos el timer 3
    while (1) {

    }

    return 0;
}

void init_gpio(void) {
    // Encender la señal de reloj para el GPIOA
    RCC->AHB1ENR |= (1<<0);
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN_Msk;

    //COnfigurar el PIN A5 como salida push_pull
    GPIOA->MODER &= ~(0b11 << GPIO_MODER_MODE5_Pos); //Limpiar la posicion
    GPIOA->MODER |= (0b01 << GPIO_MODER_MODE5_Pos); //Configurar como salida
    
    GPIOA->OTYPER &= ~(GPIO_OTYPER_OT5); //Limpiar la pisicion 5, configuramos como salida push_pull

    GPIOA->OSPEEDR &= ~(0b11 << GPIO_OSPEEDR_OSPEED5_Pos); //Limpiar la posicion
    GPIOA->OSPEEDR |= (0b01 << GPIO_OSPEEDR_OSPEED5_Pos); //configuramos la velocidad media

    GPIOA->PUPDR &= ~(0b11 << GPIO_PUPDR_PUPD5_Pos); //Limpiamos la posición
    
    GPIOA->ODR |= (GPIO_ODR_OD5); //Encendemos el led
}

void init_tim3(void) {
    //ENcendemos el reloj
    RCC->APB1ENR |= RCC_APB1ENR_TIM3EN;

    //Configuración del TIM3
    TIM3->CNT = 0; //Se pone el contador en 0
    TIM3->PSC = (1600 - 1); //Prescaler, el contador es de 16MHz, y se divide por 1600, entonces el contador va a contar a 10kHz, es decir, 0.1 us
    TIM3->ARR = (2500 -1 ); //el contador va hasta 2500, entonces el tiempo de overflow es de 2500 * 0.1 us = 250 us o 0.25 s

    TIM3->CR1 &= ~(0b11 << TIM_CR1_CKD_Pos); //Limpia, la señal de 16MHz pasa sin cambios al contador
    TIM3->CR1 |= (TIM_CR1_ARPE); //SE ACTIVA EL PRE-LOAD DEL APR
    TIM3->CR1 &= ~(TIM_CR1_DIR_Pos); //Limpia y configura conteo ascendente

    TIM3->DIER |= (TIM_DIER_UIE); //Activamos la interrupción por evento de actualización

    NVIC_EnableIRQ(TIM3_IRQn); //Registrar la interrupción TIM3 en el NVIC

    //Activar el contador to-do
    TIM3->CR1 |= TIM_CR1_CEN; //Activamos el contador, permitiendo que se incremente
}

//ISR DEL TIM3

void TIM3_IRQHandler(void) {
    //verificar que la bandera está en alto
    if(TIM3->SR && TIM_SR_UIF) {
        TIM3->SR &= ~TIM_SR_UIF; //Bajando la bandera de la interrupción

        //Hacemos "algo" en la interrupción
        GPIOA->ODR ^= (GPIO_ODR_OD5); //Hacemos un toggle en la posición 5 del GPIOA, es decir, encendemos o apagamos el led
    }
}
